-- Dimensión Cliente (SCD Tipo 2 para seguimiento de cambios históricos)
CREATE TABLE dim_cliente (
    sk_cliente        INTEGER        PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    id_cliente        INTEGER        NOT NULL,
    nombre            VARCHAR(255),                          -- Normalizado a Title Case sin espacios extra
    email             VARCHAR(255),                          -- NULL si formato inválido
    ciudad            VARCHAR(150),                          -- Estandarizado a mayúsculas
    fecha_alta        DATE,
    categoria_cliente VARCHAR(20)    NOT NULL DEFAULT 'REGULAR', -- FRECUENTE o REGULAR según regla de negocio
    fecha_inicio      DATE           NOT NULL,
    fecha_fin         DATE,
    es_vigente        BOOLEAN        NOT NULL DEFAULT TRUE
);

COMMENT ON TABLE dim_cliente IS 'Dimensión de clientes con SCD Tipo 2 para seguimiento de cambios históricos';
COMMENT ON COLUMN dim_cliente.categoria_cliente IS 'FRECUENTE si tiene más de 3 ventas en el período, REGULAR en caso contrario';
COMMENT ON COLUMN dim_cliente.email IS 'NULL cuando el email de origen no cumple formato válido';

-- Dimensión Producto
CREATE TABLE dim_producto (
    sk_producto       INTEGER        PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    id_producto       VARCHAR(100)   NOT NULL,
    descripcion       VARCHAR(500),
    categoria         VARCHAR(150),
    precio_lista      NUMERIC(15,2),
    fecha_inicio      DATE           NOT NULL,
    fecha_fin         DATE,
    es_vigente        BOOLEAN        NOT NULL DEFAULT TRUE
);

COMMENT ON TABLE dim_producto IS 'Dimensión de productos con SCD Tipo 2';

-- Dimensión Tiempo
CREATE TABLE dim_tiempo (
    sk_tiempo         INTEGER        PRIMARY KEY,             -- Formato YYYYMMDD como clave natural
    fecha             DATE           NOT NULL UNIQUE,
    anio              INTEGER        NOT NULL,
    trimestre         INTEGER        NOT NULL,                -- 1 a 4
    mes               INTEGER        NOT NULL,                -- 1 a 12
    nombre_mes        VARCHAR(20)    NOT NULL,
    dia_semana        INTEGER        NOT NULL,                -- 1=Lunes ... 7=Domingo (ISO)
    nombre_dia        VARCHAR(20)    NOT NULL,
    es_fin_de_semana  BOOLEAN        NOT NULL DEFAULT FALSE
);

COMMENT ON TABLE dim_tiempo IS 'Dimensión de tiempo con granularidad diaria. Solo fechas >= 2026-01-01';
COMMENT ON COLUMN dim_tiempo.sk_tiempo IS 'Surrogate key en formato YYYYMMDD';
COMMENT ON COLUMN dim_tiempo.dia_semana IS 'Número de día ISO: 1=Lunes, 7=Domingo';

-- Tabla de Hechos de Ventas
CREATE TABLE fact_ventas (
    sk_venta          INTEGER        PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    id_venta          INTEGER        NOT NULL,                -- Clave natural de la fuente
    fk_cliente        INTEGER        NOT NULL REFERENCES dim_cliente(sk_cliente),
    fk_producto       INTEGER        NOT NULL REFERENCES dim_producto(sk_producto),
    fk_tiempo         INTEGER        NOT NULL REFERENCES dim_tiempo(sk_tiempo),
    cantidad          INTEGER        NOT NULL,
    precio_unit       NUMERIC(15,2)  NOT NULL,
    descuento         NUMERIC(10,4)  NOT NULL DEFAULT 0,
    monto_total       NUMERIC(15,2)  NOT NULL,               -- cantidad * precio_unit * (1 - descuento/100)
    stg_fecha_carga   TIMESTAMP      NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE fact_ventas IS 'Tabla de hechos de ventas. Solo incluye ventas con fecha >= 2026-01-01, cantidad > 0 y precio_unit > 0';
COMMENT ON COLUMN fact_ventas.monto_total IS 'Calculado como cantidad * precio_unit * (1 - descuento / 100)';
COMMENT ON COLUMN fact_ventas.descuento IS 'Porcentaje de descuento aplicado a la venta';
